class Cart:
    def __init__(self, free_shipping_threshold: float = 100.0, shipping_cost: float = 15.0) -> None:
        self.free_shipping_threshold = free_shipping_threshold
        self.shipping_cost = shipping_cost
        self.items = []  # list of (name, unit_price, quantity)
        self.discounts = []  # list of percentages
        self.vouchers = []  # list of fixed amounts

    def add(self, name: str, unit_price: float, quantity: int = 1) -> None:
        if quantity <= 0:
            raise ValueError("Quantity must be greater than zero")
        self.items.append((name, unit_price, quantity))

    def apply_discount(self, percent: float) -> None:
        self.discounts.append(percent)

    def apply_voucher(self, amount: float) -> None:
        self.vouchers.append(amount)

    def total(self) -> float:
        items_total = sum(unit_price * quantity for _, unit_price, quantity in self.items)

        # Best discount: largest percentage reduction
        best_discount_reduction = 0.0
        for percent in self.discounts:
            reduction = items_total * (percent / 100.0)
            if reduction > best_discount_reduction:
                best_discount_reduction = reduction

        # Best voucher: largest fixed amount (capped at items_total)
        best_voucher_reduction = 0.0
        for amount in self.vouchers:
            reduction = min(amount, items_total)
            if reduction > best_voucher_reduction:
                best_voucher_reduction = reduction

        # Only one of them applies: the one saving the most
        saving = max(best_discount_reduction, best_voucher_reduction)
        payable_items = items_total - saving

        # Free shipping based on value before discounts
        shipping = 0.0 if items_total >= self.free_shipping_threshold else self.shipping_cost

        return round(payable_items + shipping, 2)
